"use strict";(globalThis.webpackChunksap_ai_sdk_documentation||=[]).push([[6346],{2991(e,n,s){s.r(n),s.d(n,{assets:()=>m,contentTitle:()=>r,default:()=>d,frontMatter:()=>i,metadata:()=>o,toc:()=>_});const o=JSON.parse('{"id":"examples/ai-vs-ai","title":"AI vs AI","description":"This example demonstrates a multi-model conversation where two LLMs talk to each other using LangChain, each maintaining its own message history via RunnableWithMessageHistory.","source":"@site/docs-python/examples/ai-vs-ai.mdx","sourceDirName":"examples","slug":"/examples/ai-vs-ai","permalink":"/ai-sdk/docs/python/examples/ai-vs-ai","draft":false,"unlisted":false,"editUrl":"https://github.com/SAP/ai-sdk/edit/main/docs-python/examples/ai-vs-ai.mdx","tags":[],"version":"current","frontMatter":{"id":"ai-vs-ai","title":"AI vs AI","hide_title":false,"hide_table_of_contents":false},"sidebar":"docsPythonSidebar","previous":{"title":"Metering for AI Units","permalink":"/ai-sdk/docs/python/examples/metering"}}');var t=s(4848),a=s(8453);const i={id:"ai-vs-ai",title:"AI vs AI",hide_title:!1,hide_table_of_contents:!1},r=void 0,m={},_=[];function l(e){const n={code:"code",p:"p",pre:"pre",...(0,a.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsxs)(n.p,{children:["This example demonstrates a multi-model conversation where two LLMs talk to each other using LangChain, each maintaining its own message history via ",(0,t.jsx)(n.code,{children:"RunnableWithMessageHistory"}),"."]}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-python",children:'import uuid\nfrom random import sample\nfrom time import sleep\n\nfrom langchain_classic.prompts.chat import ChatPromptTemplate, MessagesPlaceholder\nfrom langchain_community.chat_message_histories.in_memory import ChatMessageHistory\nfrom langchain_core.chat_history import BaseChatMessageHistory\nfrom langchain_core.messages import HumanMessage\nfrom langchain_core.runnables.history import RunnableWithMessageHistory\n\nfrom gen_ai_hub.proxy.langchain.amazon import ChatBedrock\nfrom gen_ai_hub.proxy.langchain.openai import ChatOpenAI\n\nstore = {}\n\navailable_models = [\n    {\n        "model_class": ChatBedrock,\n        "model_kwargs": {"model_name": "amazon--titan-text-express"},\n        "speaking_name": "Amazon Titan Text Express",\n    },\n    {\n        "model_class": ChatBedrock,\n        "model_kwargs": {"model_name": "anthropic--claude-3-haiku"},\n        "speaking_name": "Anthropic Claude 3 Haiku",\n    },\n    {\n        "model_class": ChatOpenAI,\n        "model_kwargs": {"proxy_model_name": "gpt-4o-mini"},\n        "speaking_name": "GPT 4o mini",\n    },\n]\n\n\ndef get_session_history(session_id: str) -> BaseChatMessageHistory:\n    if session_id not in store:\n        store[session_id] = ChatMessageHistory()\n    return store[session_id]\n\n\ndef create_session_history() -> str:\n    session_id = str(uuid.uuid4())\n    store[session_id] = ChatMessageHistory()\n    return session_id\n\n\ndef create_instructed_model(base_model, speaking_name, session_id):\n    prompt = ChatPromptTemplate.from_messages([\n        (\n            "system",\n            "You are the large language model {llmname}. Your goal is to answer questions nicely and keep a "\n            "conversation going. Add a creative question unrelated to the previous conversation at the end of "\n            "your answer. Also do everything with a pirate accent!",\n        ),\n        MessagesPlaceholder(variable_name="messages"),\n    ])\n    return {\n        "model": prompt | base_model,\n        "speaking_name": speaking_name,\n        "session_id": session_id,\n    }\n\n\ndef converse_ai(model_dict, prompt) -> str:\n    config = {"configurable": {"session_id": model_dict["session_id"]}}\n    model_with_message_history = RunnableWithMessageHistory(\n        model_dict["model"],\n        get_session_history,\n        input_messages_key="messages",\n    )\n    response = model_with_message_history.invoke(\n        {"messages": [HumanMessage(content=prompt)], "llmname": model_dict["speaking_name"]},\n        config=config,\n    )\n    return response.content\n\n\ndef main():\n    session_id_model_1 = create_session_history()\n    session_id_model_2 = create_session_history()\n\n    model_1, model_2 = sample(available_models, 2)\n\n    model_1 = create_instructed_model(\n        model_1["model_class"](**model_1["model_kwargs"]),\n        speaking_name=model_1["speaking_name"],\n        session_id=session_id_model_1,\n    )\n    model_2 = create_instructed_model(\n        model_2["model_class"](**model_2["model_kwargs"]),\n        speaking_name=model_2["speaking_name"],\n        session_id=session_id_model_2,\n    )\n\n    model_of_next_turn = model_2\n    model_of_last_turn = model_1\n    last_response = "Introduce yourself."\n\n    for _ in range(1, 11):\n        last_response = converse_ai(model_of_next_turn, last_response)\n        print("#########################################################")\n        print(model_of_next_turn["speaking_name"] + ": " + last_response)\n        print("#########################################################")\n        model_of_next_turn, model_of_last_turn = model_of_last_turn, model_of_next_turn\n        sleep(3)\n\n\nif __name__ == "__main__":\n    main()\n'})})]})}function d(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(l,{...e})}):l(e)}},8453(e,n,s){s.d(n,{R:()=>i,x:()=>r});var o=s(6540);const t={},a=o.createContext(t);function i(e){const n=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:i(e.components),o.createElement(a.Provider,{value:n},e.children)}}}]);